/**
 * Daily synthesis collection: gather everything new since the last digest —
 * canonical bookmark rows across all sources plus project activity deltas.
 */

import { pathExists, readJson, readJsonLines } from '../fs.js';
import { getCanonicalBookmarksSince, type CanonicalRecentItem } from '../canonical-bookmarks-db.js';
import { projectsCachePath } from '../projects/paths.js';
import type { ProjectRecord } from '../projects/types.js';
import { dailyMetaPath } from './paths.js';

const DEFAULT_WINDOW_HOURS = 24;
const MAX_WINDOW_HOURS = 24 * 7;
const MAX_ITEMS = 200;

export interface DailyMeta {
  lastRunAt?: string;
  lastDigestDate?: string;
}

export interface DailyProjectDelta {
  repo: string;
  commits: { date: string; subject: string }[];
  prompts: { timestamp: string; text: string }[];
}

export interface DailyCollection {
  date: string;
  sinceIso: string;
  untilIso: string;
  items: CanonicalRecentItem[];
  projectDeltas: DailyProjectDelta[];
}

export interface CollectDailyOptions {
  /** Explicit digest date (YYYY-MM-DD); window becomes that UTC day. */
  date?: string;
  /** Window size when no date and no watermark is available. Default: 24. */
  windowHours?: number;
  /** Stable clock injection for tests. */
  now?: Date;
}

export async function readDailyMeta(): Promise<DailyMeta> {
  const metaPath = dailyMetaPath();
  if (!(await pathExists(metaPath))) return {};
  try {
    return await readJson<DailyMeta>(metaPath);
  } catch {
    return {};
  }
}

function windowFor(options: CollectDailyOptions, meta: DailyMeta): { date: string; sinceIso: string; untilIso: string } {
  const now = options.now ?? new Date();

  if (options.date) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(options.date)) {
      throw new Error(`Invalid --date (expected YYYY-MM-DD): ${options.date}`);
    }
    const start = new Date(`${options.date}T00:00:00.000Z`);
    if (Number.isNaN(start.getTime())) throw new Error(`Invalid --date: ${options.date}`);
    const end = new Date(start.getTime() + 24 * 60 * 60 * 1000);
    return { date: options.date, sinceIso: start.toISOString(), untilIso: end.toISOString() };
  }

  const windowHours = Math.min(options.windowHours ?? DEFAULT_WINDOW_HOURS, MAX_WINDOW_HOURS);
  const fallbackSince = new Date(now.getTime() - windowHours * 60 * 60 * 1000);
  const watermark = meta.lastRunAt ? new Date(meta.lastRunAt) : null;
  const oldestAllowed = new Date(now.getTime() - MAX_WINDOW_HOURS * 60 * 60 * 1000);

  let since = watermark && !Number.isNaN(watermark.getTime()) ? watermark : fallbackSince;
  if (since.getTime() < oldestAllowed.getTime()) since = oldestAllowed;
  if (since.getTime() > now.getTime()) since = fallbackSince;

  return { date: now.toISOString().slice(0, 10), sinceIso: since.toISOString(), untilIso: now.toISOString() };
}

function withinWindow(iso: string | undefined, sinceIso: string, untilIso: string): boolean {
  if (!iso) return false;
  // Timestamps come in mixed formats (ISO with offsets, Twitter-style) —
  // compare parsed epochs, never raw strings.
  const ms = Date.parse(iso);
  if (!Number.isFinite(ms)) return false;
  return ms >= Date.parse(sinceIso) && ms < Date.parse(untilIso);
}

async function collectProjectDeltas(sinceIso: string, untilIso: string): Promise<DailyProjectDelta[]> {
  const cachePath = projectsCachePath();
  if (!(await pathExists(cachePath))) return [];

  const records = await readJsonLines<ProjectRecord>(cachePath);
  const deltas: DailyProjectDelta[] = [];

  for (const record of records) {
    const commits = record.recentCommits
      .filter((commit) => withinWindow(commit.date, sinceIso, untilIso))
      .map((commit) => ({ date: commit.date, subject: commit.subject }));
    const prompts = (record.recentPrompts ?? [])
      .filter((prompt) => withinWindow(prompt.timestamp, sinceIso, untilIso))
      .map((prompt) => ({ timestamp: prompt.timestamp, text: prompt.text }));
    if (commits.length > 0 || prompts.length > 0) {
      deltas.push({ repo: record.repo, commits, prompts });
    }
  }

  return deltas.sort((a, b) => (b.commits.length + b.prompts.length) - (a.commits.length + a.prompts.length));
}

export async function collectDaily(options: CollectDailyOptions = {}): Promise<DailyCollection> {
  const meta = await readDailyMeta();
  const { date, sinceIso, untilIso } = windowFor(options, meta);

  const items = (await getCanonicalBookmarksSince(sinceIso, MAX_ITEMS))
    .filter((item) => withinWindow(item.firstSavedAt ?? undefined, sinceIso, untilIso));
  const projectDeltas = await collectProjectDeltas(sinceIso, untilIso);

  return { date, sinceIso, untilIso, items, projectDeltas };
}
/**
 * Daily synthesis: turn the collected + connected material into a themed
 * markdown digest via the LLM engine chain, with citation validation so the
 * digest can never reference items that were not actually collected.
 */

import path from 'node:path';

import { pathExists, writeJson } from '../fs.js';
import { writeMd } from '../fs.js';
import { invokeEngineAsync, resolveEngine, withSystemOverride, type EngineRunProfile } from '../engine.js';
import { extractJsonArray } from '../bookmark-classify-llm.js';
import type { CanonicalRecentItem } from '../canonical-bookmarks-db.js';
import { loadYoutubeState } from '../youtube/state.js';
import type { DailyCollection } from './collect.js';
import type { ConnectedItem, RelatedRef } from './connect.js';
import { dailyDigestPath, dailyMetaPath, ensureDailyDir, ensureDailyLibraryDir } from './paths.js';

const SNIPPET_CHARS = 240;
const MAX_THEMES = 7;

export interface DailyTheme {
  title: string;
  summary: string;
  itemIds: string[];
  relatedIds: string[];
  projects: string[];
}

export interface SynthesizeDailyOptions {
  profile?: EngineRunProfile;
  /** Test seam: replaces engine resolution + invocation. */
  invoke?: (prompt: string) => Promise<string>;
  /** Overwrite an existing digest for the same date. */
  force?: boolean;
}

export interface SynthesizeDailyResult {
  digestPath: string;
  themes: DailyTheme[];
  usedLlm: boolean;
  droppedCitations: number;
  themedCount: number;
  alsoSavedCount: number;
  skipped: boolean;
}

function snippet(item: CanonicalRecentItem): string {
  return item.searchText.replace(/\s+/g, ' ').slice(0, SNIPPET_CHARS);
}

export interface DailyAliases {
  /** Short prompt alias (i1, r2, ...) → real canonical id. */
  items: Map<string, string>;
  related: Map<string, string>;
}

/** Long canonical hash ids get mangled by smaller models; the prompt uses
 *  short ordinal aliases (i1/r1) and citations are mapped back locally. */
export function buildDailyAliases(collection: DailyCollection, connected: ConnectedItem[]): DailyAliases {
  const items = new Map<string, string>();
  collection.items.forEach((item, index) => items.set(`i${index + 1}`, item.id));

  const related = new Map<string, string>();
  const seen = new Set<string>();
  let counter = 0;
  for (const { related: refs } of connected) {
    for (const ref of refs) {
      if (seen.has(ref.id)) continue;
      seen.add(ref.id);
      counter += 1;
      related.set(`r${counter}`, ref.id);
    }
  }
  return { items, related };
}

export function buildDailyPrompt(collection: DailyCollection, connected: ConnectedItem[], aliases: DailyAliases): string {
  const itemAlias = new Map([...aliases.items.entries()].map(([alias, id]) => [id, alias]));
  const relatedAlias = new Map([...aliases.related.entries()].map(([alias, id]) => [id, alias]));

  const lines: string[] = [];
  lines.push(`Date: ${collection.date}`);
  lines.push('');
  lines.push('NEW ITEMS (saved today):');
  for (const { item, related } of connected) {
    lines.push(`- id=${itemAlias.get(item.id)} source=${item.sources.join(',')} title=${JSON.stringify(item.displayTitle ?? item.canonicalUrl ?? item.id)}`);
    lines.push(`  snippet: ${snippet(item)}`);
    for (const ref of related) {
      lines.push(`  related: id=${relatedAlias.get(ref.id)} title=${JSON.stringify(ref.title ?? ref.url ?? ref.id)}`);
    }
  }
  lines.push('');
  lines.push('PROJECT ACTIVITY (repos worked on in this window):');
  for (const delta of collection.projectDeltas) {
    const subjects = delta.commits.slice(0, 5).map((commit) => commit.subject).join('; ');
    const questions = delta.prompts.slice(0, 3).map((prompt) => prompt.text.slice(0, 120)).join(' | ');
    lines.push(`- repo=${delta.repo} commits=[${subjects}] questions=[${questions}]`);
  }
  lines.push('');
  lines.push(`TASK: Group the new items into 3-${MAX_THEMES} themes. Respond with ONLY a JSON array:`);
  lines.push('[{"title": "...", "summary": "2-4 sentences on what is new and why it matters together",');
  lines.push('  "itemIds": ["<id like i1 from NEW ITEMS>"], "relatedIds": ["<id like r1 from related lines>"], "projects": ["<repo from PROJECT ACTIVITY>"]}]');
  lines.push('Rules: cite only the short ids (i1, i2, r1, ...) and repo names that appear verbatim above. Mention a project only when a theme genuinely connects to that repo\'s activity. Do not invent items, ids, or repos.');

  return withSystemOverride('personal knowledge-synthesis engine that groups newly saved reading material into themes', lines.join('\n'));
}

export function validateThemes(raw: unknown, collection: DailyCollection, connected: ConnectedItem[], aliases: DailyAliases): { themes: DailyTheme[]; dropped: number } {
  const repos = new Set(collection.projectDeltas.map((delta) => delta.repo));
  const citedItems = new Set<string>();
  const themes: DailyTheme[] = [];
  let dropped = 0;

  if (!Array.isArray(raw)) return { themes, dropped };

  for (const entry of raw.slice(0, MAX_THEMES)) {
    if (!entry || typeof entry !== 'object') continue;
    const candidate = entry as Record<string, unknown>;
    const title = typeof candidate.title === 'string' ? candidate.title.trim() : '';
    const summary = typeof candidate.summary === 'string' ? candidate.summary.trim() : '';
    if (!title || !summary) continue;

    const mapAliases = (value: unknown, aliasMap: Map<string, string>): { kept: string[]; removed: number } => {
      if (!Array.isArray(value)) return { kept: [], removed: 0 };
      const kept: string[] = [];
      let removed = 0;
      for (const alias of value) {
        const real = typeof alias === 'string' ? aliasMap.get(alias.trim()) : undefined;
        if (real && !kept.includes(real)) kept.push(real);
        else removed += 1;
      }
      return { kept, removed };
    };

    const keepRepos = (value: unknown): { kept: string[]; removed: number } => {
      if (!Array.isArray(value)) return { kept: [], removed: 0 };
      const kept: string[] = [];
      let removed = 0;
      for (const repo of value) {
        if (typeof repo === 'string' && repos.has(repo) && !kept.includes(repo)) kept.push(repo);
        else removed += 1;
      }
      return { kept, removed };
    };

    const items = mapAliases(candidate.itemIds, aliases.items);
    const uniqueItems = items.kept.filter((id) => {
      if (citedItems.has(id)) return false;
      citedItems.add(id);
      return true;
    });
    const related = mapAliases(candidate.relatedIds, aliases.related);
    const projects = keepRepos(candidate.projects);
    dropped += items.removed + related.removed + projects.removed;

    if (uniqueItems.length === 0) {
      continue;
    }

    themes.push({ title, summary, itemIds: uniqueItems, relatedIds: related.kept, projects: projects.kept });
  }

  return { themes, dropped };
}

function mechanicalThemes(collection: DailyCollection): DailyTheme[] {
  const bySource = new Map<string, string[]>();
  for (const item of collection.items) {
    const key = item.sources[0] ?? 'other';
    const list = bySource.get(key) ?? [];
    list.push(item.id);
    bySource.set(key, list);
  }
  return [...bySource.entries()].map(([source, ids]) => ({
    title: `New from ${source}`,
    summary: `${ids.length} item(s) saved from ${source} in this window.`,
    itemIds: ids,
    relatedIds: [],
    projects: [],
  }));
}

/** Pull a YouTube video id out of watch/youtu.be/shorts/embed URLs. */
export function extractYoutubeVideoId(url: string | null | undefined): string | null {
  if (!url) return null;
  const match = url.match(
    /(?:youtube\.com\/(?:watch\?(?:[^#]*&)?v=|shorts\/|embed\/|live\/)|youtu\.be\/)([\w-]{6,})/,
  );
  return match ? match[1] : null;
}

/** Map videoId → digest-relative link to its library notes .md, for every
 *  YouTube URL among the digest's items and related refs. */
export async function buildYoutubeNotesLinks(
  urls: Array<string | null | undefined>,
  digestPath: string,
): Promise<Map<string, string>> {
  const links = new Map<string, string>();
  const videoIds = new Set<string>();
  for (const url of urls) {
    const videoId = extractYoutubeVideoId(url);
    if (videoId) videoIds.add(videoId);
  }
  if (videoIds.size === 0) return links;

  let state;
  try {
    state = await loadYoutubeState();
  } catch {
    return links;
  }
  const digestDir = path.dirname(digestPath);
  for (const videoId of videoIds) {
    const notesPath = state.videos[videoId]?.artifacts?.notesPath;
    if (!notesPath || !(await pathExists(notesPath))) continue;
    links.set(videoId, path.relative(digestDir, notesPath).split(path.sep).join('/'));
  }
  return links;
